package ru.local.jarvis;
import android.app.*;import android.content.*;import android.content.pm.*;import android.hardware.camera2.*;import android.media.*;import android.net.Uri;import android.os.*;import android.provider.Settings;import android.view.KeyEvent;import org.json.*;import java.util.*;import java.util.concurrent.*;

final class DeviceControls {
 static final Set<String> KINDS=new HashSet<>(Arrays.asList("app","website","flashlight","volume","brightness","dnd","wifi","bluetooth","camera","media"));
 static boolean handles(String kind){return KINDS.contains(kind);}
 static String tr(JSONObject a,String ru,String en){return "en".equals(a.optString("language"))?en:ru;}
 static boolean direct(Context c,String kind){return kind.equals("volume")||kind.equals("media")||kind.equals("flashlight")&&c.checkSelfPermission("android.permission.CAMERA")==0||kind.equals("brightness")&&Settings.System.canWrite(c)||kind.equals("dnd")&&c.getSystemService(NotificationManager.class).isNotificationPolicyAccessGranted();}
 static int level(JSONObject a,int old,int max,int step)throws Exception{int value;if(a.has("percent")){int percent=a.getInt("percent");if(percent<0||percent>100)throw new Exception("Invalid percentage");value=Math.round(max*percent/100f);}else{String direction=a.getString("direction");if(!direction.equals("up")&&!direction.equals("down"))throw new Exception("Invalid direction");value=old+(direction.equals("up")?step:-step);}return Math.max(0,Math.min(max,value));}
 static String execute(Context c,JSONObject a)throws Exception{
  String kind=a.getString("kind");
  if(kind.equals("volume")){AudioManager m=c.getSystemService(AudioManager.class);String stream=a.optString("stream","media");int id=stream.equals("ring")?AudioManager.STREAM_RING:stream.equals("alarm")?AudioManager.STREAM_ALARM:AudioManager.STREAM_MUSIC;int max=m.getStreamMaxVolume(id),old=m.getStreamVolume(id),value=level(a,old,max,Math.max(1,Math.round(max*.1f)));m.setStreamVolume(id,value,0);int actual=m.getStreamVolume(id);return tr(a,"Громкость: ","Volume: ")+Math.round(actual*100f/Math.max(1,max))+"%";}
  if(kind.equals("brightness")){if(!Settings.System.canWrite(c))throw new Exception("Screen settings permission required");int old=Settings.System.getInt(c.getContentResolver(),Settings.System.SCREEN_BRIGHTNESS,128),value=Math.max(1,level(a,old,255,26));if(!Settings.System.putInt(c.getContentResolver(),Settings.System.SCREEN_BRIGHTNESS_MODE,Settings.System.SCREEN_BRIGHTNESS_MODE_MANUAL)||!Settings.System.putInt(c.getContentResolver(),Settings.System.SCREEN_BRIGHTNESS,value))throw new Exception("Screen settings update rejected");int actual=Settings.System.getInt(c.getContentResolver(),Settings.System.SCREEN_BRIGHTNESS);return tr(a,"Яркость: ","Brightness: ")+Math.round(actual*100f/255)+"%";}
  if(kind.equals("dnd")){NotificationManager m=c.getSystemService(NotificationManager.class);if(!m.isNotificationPolicyAccessGranted())throw new Exception("Notification policy access required");boolean enabled=a.getBoolean("enabled");m.setInterruptionFilter(enabled?NotificationManager.INTERRUPTION_FILTER_PRIORITY:NotificationManager.INTERRUPTION_FILTER_ALL);boolean actual=m.getCurrentInterruptionFilter()!=NotificationManager.INTERRUPTION_FILTER_ALL;if(actual!=enabled)throw new Exception("DND state was not confirmed");return enabled?tr(a,"Режим «Не беспокоить» включён","Do Not Disturb enabled"):tr(a,"Режим «Не беспокоить» выключен","Do Not Disturb disabled");}
  if(kind.equals("flashlight")){CameraManager manager=c.getSystemService(CameraManager.class);String selected=null;for(String id:manager.getCameraIdList()){CameraCharacteristics x=manager.getCameraCharacteristics(id);if(Boolean.TRUE.equals(x.get(CameraCharacteristics.FLASH_INFO_AVAILABLE))&&Integer.valueOf(CameraCharacteristics.LENS_FACING_BACK).equals(x.get(CameraCharacteristics.LENS_FACING))){selected=id;break;}}if(selected==null)throw new Exception("Flashlight unavailable");final String camera=selected;boolean enabled=a.getBoolean("enabled");CountDownLatch ready=new CountDownLatch(1);CameraManager.TorchCallback cb=new CameraManager.TorchCallback(){public void onTorchModeChanged(String id,boolean state){if(id.equals(camera)&&state==enabled)ready.countDown();}};manager.registerTorchCallback(cb,new Handler(Looper.getMainLooper()));try{manager.setTorchMode(camera,enabled);if(!ready.await(3,TimeUnit.SECONDS))throw new Exception("Torch command sent; state not confirmed");}finally{manager.unregisterTorchCallback(cb);}return enabled?tr(a,"Фонарик включён","Flashlight enabled"):tr(a,"Фонарик выключен","Flashlight disabled");}
  if(kind.equals("media")){String command=a.getString("command");int key=command.equals("play")?KeyEvent.KEYCODE_MEDIA_PLAY:command.equals("pause")?KeyEvent.KEYCODE_MEDIA_PAUSE:command.equals("next")?KeyEvent.KEYCODE_MEDIA_NEXT:command.equals("previous")?KeyEvent.KEYCODE_MEDIA_PREVIOUS:0;if(key==0)throw new Exception("Invalid media command");AudioManager m=c.getSystemService(AudioManager.class);m.dispatchMediaKeyEvent(new KeyEvent(KeyEvent.ACTION_DOWN,key));m.dispatchMediaKeyEvent(new KeyEvent(KeyEvent.ACTION_UP,key));return tr(a,"Команда передана активному плееру; состояние воспроизведения не проверялось","Command sent to the active player; playback state not verified");}
  throw new Exception("This action requires a screen");
 }
 static boolean access(Activity screen,JSONObject a)throws Exception{
  String kind=a.getString("kind");if(kind.equals("flashlight")||kind.equals("camera")){if(screen.checkSelfPermission("android.permission.CAMERA")!=0){screen.requestPermissions(new String[]{"android.permission.CAMERA"},71);return false;}}
  if(kind.equals("bluetooth")&&a.optBoolean("enabled")&&Build.VERSION.SDK_INT>=31&&screen.checkSelfPermission("android.permission.BLUETOOTH_CONNECT")!=0){screen.requestPermissions(new String[]{"android.permission.BLUETOOTH_CONNECT"},71);return false;}
  if(kind.equals("brightness")&&!Settings.System.canWrite(screen)){screen.startActivityForResult(new Intent(Settings.ACTION_MANAGE_WRITE_SETTINGS,Uri.parse("package:"+screen.getPackageName())),77);return false;}
  if(kind.equals("dnd")&&!screen.getSystemService(NotificationManager.class).isNotificationPolicyAccessGranted()){screen.startActivityForResult(new Intent(Settings.ACTION_NOTIFICATION_POLICY_ACCESS_SETTINGS),77);return false;}
  return true;
 }
 static void run(ActionScreen screen,JSONObject a){try{
  if(!access(screen,a))return;
  String kind=a.getString("kind");
  if(Arrays.asList("volume","brightness","dnd","flashlight","media").contains(kind)){new Thread(()->{try{String result=execute(screen,a);screen.runOnUiThread(()->screen.done(result));}catch(Exception e){screen.runOnUiThread(()->screen.error(tr(a,"Не удалось выполнить команду: ","Could not execute command: ")+e.getMessage()));}},"JarvisDeviceAction").start();return;}
  if(kind.equals("app")){openApp(screen,a);return;}
  Intent intent;String result;
  if(kind.equals("website")){String target=a.getString("target");Uri uri=Uri.parse(target);if(!Arrays.asList("https","http").contains(uri.getScheme())||uri.getHost()==null||uri.getUserInfo()!=null||target.matches("(?s).*[\\x00-\\x20\\\\].*"))throw new Exception("Invalid website URL");intent=new Intent(Intent.ACTION_VIEW,uri).addCategory(Intent.CATEGORY_BROWSABLE);Intent chrome=new Intent(intent).setPackage("com.android.chrome");if(chrome.resolveActivity(screen.getPackageManager())!=null)intent=chrome;result=tr(a,"Сайт открыт в браузере","Website opened in browser");}
  else if(kind.equals("wifi")){intent=new Intent("android.settings.panel.action.WIFI");result=tr(a,"Открыто системное окно Wi-Fi. Выберите нужное состояние вручную.","Wi-Fi controls opened. Select the desired state manually.");}
  else if(kind.equals("bluetooth")){intent=new Intent(a.getBoolean("enabled")?"android.bluetooth.adapter.action.REQUEST_ENABLE":Settings.ACTION_BLUETOOTH_SETTINGS);result=tr(a,"Открыто системное управление Bluetooth; подтвердите изменение.","Bluetooth controls opened; confirm the change.");}
  else if(kind.equals("camera")){boolean front=a.optString("facing").equals("front");intent=new Intent("android.media.action.STILL_IMAGE_CAMERA");intent.putExtra("android.intent.extras.CAMERA_FACING",front?1:0);intent.putExtra("android.intent.extra.USE_FRONT_CAMERA",front);intent.putExtra("android.intent.extras.LENS_FACING_FRONT",front?1:0);result=tr(a,"Камера открыта. Выбор фронтальной камеры зависит от приложения; снимок не сделан.","Camera opened. Front-camera selection depends on the camera app; no photo was taken.");}
  else throw new Exception("Unsupported screen action");
  screen.startActivity(intent);screen.done(result);
 }catch(Exception e){screen.error(tr(a,"Не удалось выполнить команду: ","Could not execute command: ")+e.getMessage());}}
 static void openApp(ActionScreen screen,JSONObject a)throws Exception{
  String target=a.getString("target").trim().toLowerCase(Locale.ROOT);Map<String,String> aliases=new HashMap<>();aliases.put("youtube","com.google.android.youtube");aliases.put("ютуб","com.google.android.youtube");aliases.put("telegram","org.telegram.messenger");aliases.put("телеграм","org.telegram.messenger");aliases.put("chrome","com.android.chrome");aliases.put("хром","com.android.chrome");aliases.put("whatsapp","com.whatsapp");aliases.put("ватсап","com.whatsapp");aliases.put("настройки","com.android.settings");aliases.put("settings","com.android.settings");
  PackageManager pm=screen.getPackageManager();String pkg=aliases.get(target);if(pkg!=null){Intent launch=pm.getLaunchIntentForPackage(pkg);if(launch!=null){screen.startActivity(launch);screen.done(tr(a,"Приложение открыто: ","Application opened: ")+a.getString("target"));return;}}
  List<ResolveInfo> all=pm.queryIntentActivities(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER),0),found=new ArrayList<>(),exact=new ArrayList<>();Set<String> seen=new HashSet<>();for(ResolveInfo item:all){String label=item.loadLabel(pm).toString().toLowerCase(Locale.ROOT);if(label.equals(target)||item.activityInfo.packageName.equals(target))exact.add(item);if(label.contains(target)&&seen.add(item.activityInfo.packageName))found.add(item);}if(!exact.isEmpty())found=exact;
  if(found.isEmpty())throw new Exception(tr(a,"Приложение не найдено: ","Application not found: ")+a.getString("target"));
  final List<ResolveInfo> choices=found;if(choices.size()==1){launch(screen,choices.get(0),a);return;}String[] labels=new String[choices.size()];for(int i=0;i<labels.length;i++)labels[i]=choices.get(i).loadLabel(pm).toString();new AlertDialog.Builder(screen).setTitle(tr(a,"Какое приложение открыть?","Which app should I open?")).setItems(labels,(d,w)->launch(screen,choices.get(w),a)).setNegativeButton(tr(a,"Отмена","Cancel"),(d,w)->screen.done(tr(a,"Открытие приложения отменено","App launch cancelled"))).setOnCancelListener(d->screen.done(tr(a,"Открытие приложения отменено","App launch cancelled"))).show();
 }
 static void launch(ActionScreen s,ResolveInfo app,JSONObject a){try{s.startActivity(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER).setComponent(new ComponentName(app.activityInfo.packageName,app.activityInfo.name)));s.done(tr(a,"Приложение открыто: ","Application opened: ")+app.loadLabel(s.getPackageManager()));}catch(Exception e){s.error(tr(a,"Не удалось открыть приложение","Could not open application"));}}
}
